package com.myles.cijian;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;

/** 验证实际浏览页固定操作区与大字横竖屏，不依赖截图猜测。 / Measure real browse controls at large text scales and both orientations. */
public final class Feature1105Layouts extends Instrumentation {
    private String language;private int rotation,checks;private BrowseActivity activity;
    @Override public void onCreate(Bundle args){super.onCreate(args);language=args.getString("language","ZH");rotation=Integer.parseInt(args.getString("rotation","0"));start();}
    private void ui(Runnable task){java.util.concurrent.atomic.AtomicReference<Throwable> error=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError("UI measurement",error.get());}
    private Object field(String name){try{Field f=BrowseActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new RuntimeException(e);}}
    private void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;}
    private ScrollView scroll(View v){if(v instanceof ScrollView)return (ScrollView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){ScrollView result=scroll(((ViewGroup)v).getChildAt(i));if(result!=null)return result;}return null;}
    private void measure(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView text=(TextView)v;if(text.getText().length()>0&&text.getLayout()!=null){check(text.getHeight()+2>=text.getLayout().getHeight()+text.getCompoundPaddingTop()+text.getCompoundPaddingBottom(),"Text clipped: "+text.getText());for(int i=0;i<text.getLineCount();i++)check(text.getLayout().getEllipsisCount(i)==0,"Ellipsized: "+text.getText());}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)measure(((ViewGroup)v).getChildAt(i));}
    private void fixed(ViewGroup row){Rect rect=new Rect();for(int i=0;i<row.getChildCount();i++){View child=row.getChildAt(i);check(child.getGlobalVisibleRect(rect)&&rect.width()>=child.getWidth()-2&&rect.height()>=child.getHeight()-2,"Fixed action clipped: "+((TextView)child).getText());check(child.getHeight()>=Ui.dp(activity,44),"Touch target too short");if(i>0)check(child.getLeft()-row.getChildAt(i-1).getRight()>=Ui.dp(activity,4),"Action gap too narrow");}}
    @Override public void onStart(){Bundle out=new Bundle();try{
        if(!Build.HARDWARE.equals("ranchu")&&!Build.HARDWARE.equals("goldfish"))throw new AssertionError("Emulator only");Context c=getTargetContext();new Prefs(c).data.edit().putString("uiLanguage",language).putString("theme","DARK").putString("accent","BLACK").putBoolean("languagePromptSeen",true).putBoolean("languagePromptPending",false).putBoolean("autoSpeak",false).putBoolean("speakOnFlip",false).putString("voiceEngine",c.getPackageName()+".test").putInt("appWordSize",48).putInt("appReadingSize",28).putInt("appMeaningSize",32).putBoolean("conceal",false).commit();activity=(BrowseActivity)startActivitySync(new Intent(c,BrowseActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));long until=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<until){boolean[] ready={false};ui(()->ready[0]=!(Boolean)field("busy")&&field("session")!=null);if(ready[0])break;SystemClock.sleep(30);}waitForIdleSync();
        ui(()->{check(activity.getResources().getConfiguration().orientation==(rotation==0?1:2),"Actual orientation mismatch");LinearLayout root=(LinearLayout)field("root");fixed((ViewGroup)root.getChildAt(0));fixed((ViewGroup)root.getChildAt(root.getChildCount()-1));ScrollView content=scroll(root);check(content!=null&&content.getHeight()>=Ui.dp(activity,44),"Scrollable content needs at least a 44dp viewport");measure(root);content.fullScroll(View.FOCUS_DOWN);});waitForIdleSync();ui(()->{measure((View)field("root"));activity.finish();});out.putString("stream","PASS: "+checks+" measured browse layout checks in "+language+" rotation "+rotation+"\n");finish(Activity.RESULT_OK,out);
    }catch(Throwable e){out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
